func BenchmarkSeedMetadataBranch(b *testing.B) {
	for _, count := range []int{1, 5, 10} {
		b.Run(fmt.Sprintf("%dCheckpoints", count), func(b *testing.B) {
			for b.Loop() {
				repo := NewBenchRepo(b, RepoOpts{FileCount: 10})
				repo.SeedMetadataBranch(b, count)
			}
		})
	}
}

